1	use std::collections::BTreeMap;
2	
3	/// One damaged item reported in an incident.
4	pub struct Damage {
5	    pub item_type: String,
6	    pub amount: i64,
7	}
8	
9	/// A damage report filed against an existing policy.
10	pub struct Incident {
11	    pub damages: Vec<Damage>,
12	}
13	
14	/// The single customer a scenario is quoted for.
15	pub struct Customer {
16	    pub years_with_mhpco: u32,
17	}
18	
19	pub struct Item {
20	    pub item_type: String,
21	    pub material: String,
22	    pub enchantment: u32,
23	    pub cursed: bool,
24	}
25	
26	const PROCESSING_FEE: u64 = 5;
27	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
28	
29	const SWORD_BASE_PREMIUM: u64 = 100;
30	const AMULET_BASE_PREMIUM: u64 = 60;
31	const STAFF_BASE_PREMIUM: u64 = 80;
32	const POTION_BASE_PREMIUM: u64 = 40;
33	const COMPONENT_BASE_PREMIUM: u64 = 25;
34	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
35	const COMPONENT_BLOCK_SIZE: usize = 3;
36	const CURSE_SURCHARGE_PERCENT: u64 = 50;
37	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
38	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
39	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
40	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
41	const LOYALTY_YEARS: u32 = 2;
42	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
43	
44	/// Components, such as runes and moonstones, are the parts the MHPCO insures
45	/// alongside main items and the only items the building-block offer covers.
46	fn is_component(item: &Item) -> bool {
47	    matches!(item.item_type.as_str(), "rune" | "moonstone")
48	}
49	
50	/// The MHPCO price list: the base premium the catalogue lists for one item.
51	fn base_premium(item: &Item) -> u64 {
52	    if is_component(item) {
53	        return COMPONENT_BASE_PREMIUM;
54	    }
55	    match item.item_type.as_str() {
56	        "amulet" => AMULET_BASE_PREMIUM,
57	        "staff" => STAFF_BASE_PREMIUM,
58	        "potion" => POTION_BASE_PREMIUM,
59	        _ => SWORD_BASE_PREMIUM,
60	    }
61	}
62	
63	/// The building-block offer is reserved for a group of exactly 3 alike
64	/// components; a larger group does not qualify, it is priced per component.
65	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
66	    alike_component_count == COMPONENT_BLOCK_SIZE
67	}
68	
69	/// The price the MHPCO charges for one group of alike components: the
70	/// building-block offer when the group qualifies, otherwise per component.
71	fn component_group_base_premium(count: usize) -> u64 {
72	    if qualifies_as_building_block(count) {
73	        COMPONENT_BLOCK_BASE_PREMIUM
74	    } else {
75	        count as u64 * COMPONENT_BASE_PREMIUM
76	    }
77	}
78	
79	/// Two components are "alike" when they share this key. For the MHPCO,
80	/// alike means the very same catalogue type: a rune and a moonstone are
81	/// never alike, so mixed component types form no building block.
82	fn alike_group_key(item: &Item) -> &str {
83	    &item.item_type
84	}
85	
86	/// The policy base premium: the sum of all insured items' base premiums,
87	/// with alike components priced per group so a block can be recognised.
88	fn policy_base_premium(items: &[Item]) -> u64 {
89	    let mut main_items_total = 0;
90	    let mut alike_component_counts: BTreeMap<&str, usize> = BTreeMap::new();
91	    for item in items {
92	        if is_component(item) {
93	            *alike_component_counts.entry(alike_group_key(item)).or_insert(0) += 1;
94	        } else {
95	            main_items_total += base_premium(item);
96	        }
97	    }
98	
99	    main_items_total
100	        + alike_component_counts
101	            .values()
102	            .map(|count| component_group_base_premium(*count))
103	            .sum::<u64>()
104	}
105	
106	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
107	#[derive(Clone, Copy)]
108	enum Debtor {
109	    Customer,
110	    Mhpco,
111	}
112	
113	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
114	/// settles the direction by itself once it is known who owes whom: an amount
115	/// the customer owes is rounded up, an amount the office owes is rounded down.
116	/// Intermediate amounts stay fractional; only the final amount is rounded.
117	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
118	    match owed_by {
119	        Debtor::Customer => amount.ceil() as u64,
120	        Debtor::Mhpco => amount.floor() as u64,
121	    }
122	}
123	
124	/// A policy-wide modifier is measured against the policy base premium, the
125	/// sum of all item base premiums, never against a single item.
126	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
127	    policy_base_premium * percent as f64 / 100.0
128	}
129	
130	/// Every item in a quote is treated as a first insurance, so the initial
131	/// assessment surcharge is charged on the whole policy base premium.
132	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
133	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
134	}
135	
136	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
137	/// highly enchanted. This is the premium-side threshold; the claim-side
138	/// reimbursement clause judges enchantment by its own, stricter threshold.
139	fn is_highly_enchanted(item: &Item) -> bool {
140	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
141	}
142	
143	/// An item-specific risk surcharge is charged on the base premium of the
144	/// affected item, never on the policy total.
145	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
146	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
147	}
148	
149	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
150	/// item that brings two of them is surcharged for each.
151	fn item_risk_surcharge(item: &Item) -> f64 {
152	    let mut surcharge = 0.0;
153	    if item.cursed {
154	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
155	    }
156	    if is_highly_enchanted(item) {
157	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
158	    }
159	    surcharge
160	}
161	
162	/// Item-specific modifiers apply to the base premium of the affected item,
163	/// never to the policy total, so the policy owes the sum of the items' own
164	/// risk surcharges.
165	fn item_risk_surcharges(items: &[Item]) -> f64 {
166	    items.iter().map(item_risk_surcharge).sum()
167	}
168	
169	/// A long-standing customer, with at least two years of business with the
170	/// MHPCO, has earned the loyalty discount.
171	fn is_long_standing(customer: &Customer) -> bool {
172	    customer.years_with_mhpco >= LOYALTY_YEARS
173	}
174	
175	/// The loyalty discount is a policy-wide modifier, so it is measured against
176	/// the policy base premium.
177	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
178	    if is_long_standing(customer) {
179	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
180	    } else {
181	        0.0
182	    }
183	}
184	
185	/// A contract is a follow-up when the customer already holds at least one
186	/// other contract with the MHPCO; the customer's very first is not.
187	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
188	    contracts_already_held > 0
189	}
190	
191	/// Every contract after the customer's first earns the follow-up discount. It
192	/// is a policy-wide modifier, so it is measured against the policy base premium.
193	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
194	    if is_follow_up_contract(contracts_already_held) {
195	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
196	    } else {
197	        0.0
198	    }
199	}
200	
201	/// What the customer's standing with the MHPCO adds to or takes off the policy
202	/// base premium: the net of every policy-wide surcharge and discount. Positive
203	/// amounts raise the premium, negative amounts lower it.
204	fn policy_wide_modifiers(
205	    customer: &Customer,
206	    contracts_already_held: u32,
207	    policy_base_premium: f64,
208	) -> f64 {
209	    first_insurance_surcharge(policy_base_premium)
210	        - loyalty_discount(customer, policy_base_premium)
211	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
212	}
213	
214	/// The premium the policy earns before the processing fee: the policy base
215	/// premium, plus what the items' own risks cost, plus what the customer's
216	/// standing adjusts.
217	fn modified_policy_premium(
218	    customer: &Customer,
219	    contracts_already_held: u32,
220	    items: &[Item],
221	) -> f64 {
222	    let policy_base_premium = policy_base_premium(items) as f64;
223	    policy_base_premium
224	        + item_risk_surcharges(items)
225	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
226	}
227	
228	/// The MHPCO adds its processing fee to every premium at the very end, after
229	/// every surcharge and discount has been settled.
230	pub fn quote_premium(
231	    customer: &Customer,
232	    contracts_already_held: u32,
233	    items: &[Item],
234	) -> u64 {
235	    rounded_in_mhpco_favor(
236	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
237	        Debtor::Customer,
238	    )
239	}
240	
241	/// A deductible applies per damage event, that is once per damaged item.
242	fn reimbursement_for(damage: &Damage) -> f64 {
243	    (damage.amount as f64 - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
244	}
245	
246	/// What the MHPCO owes for an incident filed against a policy: the sum of the
247	/// reimbursements its damages earn, rounded in the office's favor at the end.
248	pub fn claim_payout(_items: &[Item], incident: &Incident) -> u64 {
249	    rounded_in_mhpco_favor(
250	        incident.damages.iter().map(reimbursement_for).sum(),
251	        Debtor::Mhpco,
252	    )
253	}
